public void testValidateWithTooFewOptions() throws OptionException {
    // Create a command line with fewer options than required by the group
    WriteableCommandLine commandLine = new WriteableCommandLine("command");
    for (int i = 0; i < GROUP_OPTIONS.size() - 1; i++) {
        commandLine.addOption(GROUP_OPTIONS.get(i));
    }

    // Validate the group with the command line
    try {
        group.validate(commandLine);
        fail("Expected OptionException");
    } catch (OptionException e) {
        assertThat(e.getMessage(), containsString(ResourceConstants.MISSING_OPTION));
    }
}

